//! Reader for the baseline oracle `fixtures/object-raster-asset-item/oracle.txt`
//! (generated by running the verbatim `rasterImageRect` and `serR` of fbe4b8a3
//! over real Paper rasters; see HANDOFF.md) plus small shared test builders.
use super::geometry::{ImageRect, PendingGeometry, RasterSurface, SurfaceBounds};
use super::{RasterSourceForm, RasterTags};
use crate::object_document::{AssetId, AssetInventory, AssetKind, AssetRecord, AssetSource};
use serde_json::Value;
use std::sync::Arc;

pub(crate) const ORACLE: &str = include_str!("fixtures/object-raster-asset-item/oracle.txt");

pub(crate) struct Row {
    pub(crate) name: String,
    pub(crate) surface: RasterSurface,
    pub(crate) tags: RasterTags,
    /// `rasterImageRect(c)`.
    pub(crate) engine: ImageRect,
    /// The `serR(r)` dict without isRaster/src/linked/linkedPath/linkedHandleId.
    pub(crate) ser: Value,
    pub(crate) form: RasterSourceForm,
    pub(crate) cross_check: bool,
}

fn num(value: &Value, key: &str) -> f64 {
    value[key]
        .as_f64()
        .unwrap_or_else(|| panic!("oracle number {key} missing in {value}"))
}

pub(crate) fn rows() -> Vec<Row> {
    ORACLE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(parse_row)
        .collect()
}

fn parse_row(line: &str) -> Row {
    let v: Value = serde_json::from_str(line).expect("oracle row is JSON");
    let i = &v["in"];
    let b = &i["bounds"];
    let pending = if i["pending"].is_null() {
        None
    } else {
        let p = &i["pending"];
        Some(PendingGeometry {
            x: num(p, "x"),
            y: num(p, "y"),
            width: num(p, "width"),
            height: num(p, "height"),
            rotation: num(p, "rotation"),
        })
    };
    let data = &i["data"];
    let e = &v["engine"];
    Row {
        name: v["name"].as_str().expect("row name").to_string(),
        surface: RasterSurface {
            matrix_rotation: i["rotation"].as_f64(),
            scaling_x: num(i, "scalingX"),
            scaling_y: num(i, "scalingY"),
            width: num(i, "width"),
            height: num(i, "height"),
            position_x: num(i, "positionX"),
            position_y: num(i, "positionY"),
            bounds: SurfaceBounds {
                x: num(b, "x"),
                y: num(b, "y"),
                width: num(b, "width"),
                height: num(b, "height"),
            },
            loaded: i["loaded"].as_bool().expect("loaded"),
            pending,
            opacity: i["opacity"].as_f64(),
        },
        tags: RasterTags {
            is_bitmap_brush: data["isBitmapBrush"].as_bool().unwrap_or(false),
            brush_group_id: data["brushGroupId"].as_str().unwrap_or("").to_string(),
            is_brush_texture_copy: data["isBrushTextureCopy"].as_bool().unwrap_or(false),
            mesh_id: data["meshId"].as_str().unwrap_or("").to_string(),
        },
        engine: ImageRect {
            x: num(e, "x"),
            y: num(e, "y"),
            width: num(e, "width"),
            height: num(e, "height"),
            rotation: num(e, "rotation"),
        },
        ser: v["ser"].clone(),
        form: match v["form"].as_str() {
            Some("linked") => RasterSourceForm::Linked,
            Some("src") => RasterSourceForm::Embedded,
            other => panic!("oracle form {other:?}"),
        },
        cross_check: v["crossCheck"].as_bool().expect("crossCheck"),
    }
}

pub(crate) fn id(text: &str) -> AssetId {
    AssetId::new(text.to_string()).expect("valid asset id")
}

/// A one-asset inventory holding `asset` as the given kind and source form.
pub(crate) fn inventory(asset: &str, kind: AssetKind, form: RasterSourceForm) -> AssetInventory {
    let source = match form {
        RasterSourceForm::Embedded => AssetSource::admitted_embedded(
            "image/png".to_string(),
            Arc::new(vec![0x89, b'P', b'N', b'G']),
            4096,
        )
        .expect("embedded source"),
        RasterSourceForm::Linked => {
            AssetSource::linked("/media/a.png".to_string(), 4096).expect("linked source")
        }
    };
    let record = AssetRecord::new(id(asset), "a.png".to_string(), kind, source).expect("record");
    AssetInventory::new(vec![Arc::new(record)], vec![], 16, 16).expect("inventory")
}

pub(crate) fn row<'a>(all: &'a [Row], name: &str) -> &'a Row {
    all.iter()
        .find(|r| r.name == name)
        .unwrap_or_else(|| panic!("oracle row {name}"))
}
